    #[test]
    fn nests_observable_array_elements_across_inert_literals() {
        let code = compile_module_with_options(
            "extern JsValue cb(string s);export JsValue tuples(){JsValue row=[\"notify\",\"progress\",cb(\"memory\"),cb(\"memory\"),2.0];return [row];}",
            IrJsOptions {
                mangle_identifiers: false,
                operand_order_fusion: true,
                aggregate_operand_order_fusion: true,
                ..IrJsOptions::default()
            },
        );
        assert!(code.contains("cb(") && !code.contains("=cb("), "{code}");
        assert_eq!(code.matches("cb(").count(), 2, "{code}");

        let interleaved = compile_module_with_options(
            "extern JsValue cb(string s);export JsValue tuples(){JsValue first=cb(\"memory\");JsValue row=[\"notify\",\"progress\",first,cb(\"memory\"),2.0];return row;}",
            IrJsOptions {
                mangle_identifiers: false,
                operand_order_fusion: true,
                aggregate_operand_order_fusion: true,
                ..IrJsOptions::default()
            },
        );
        assert!(
            interleaved.contains("cb(") && !interleaved.contains("=cb("),
            "{interleaved}"
        );
        assert_eq!(interleaved.matches("cb(").count(), 2, "{interleaved}");

        let nested_rows = compile_module_with_options(
            "extern JsValue cb(string s);export JsValue tuples(){JsValue row0=[\"notify\",\"progress\",cb(\"memory\"),cb(\"memory\"),2.0];JsValue row1=[\"resolve\",\"done\",cb(\"once memory\"),cb(\"once memory\"),0.0,\"resolved\"];JsValue row2=[\"reject\",\"fail\",cb(\"once memory\"),cb(\"once memory\"),1.0,\"rejected\"];return [row0,row1,row2];}tuples();",
            IrJsOptions {
                mangle_identifiers: false,
                operand_order_fusion: true,
                aggregate_operand_order_fusion: true,
                ..IrJsOptions::default()
            },
        );
        assert!(
            nested_rows.contains("[[\"notify\"")
                && nested_rows.contains("[\"resolve\"")
                && nested_rows.contains("[\"reject\""),
            "{nested_rows}"
        );
        assert!(!nested_rows.contains("=cb("), "{nested_rows}");
        assert_eq!(nested_rows.matches("cb(").count(), 6, "{nested_rows}");
        let trace = run_javascript(&format!(
            "let events=[];function cb(value){{events.push(value);return value}};{nested_rows};process.stdout.write(events.join(','))"
        ));
        assert_eq!(
            trace, "memory,memory,once memory,once memory,once memory,once memory",
            "{nested_rows}"
        );

        let foreign_gap = compile_module_with_options(
            "extern JsValue cb(string s);extern void gap();export JsValue tuples(){JsValue row0=[\"a\",cb(\"x\")];gap();JsValue row1=[\"b\",cb(\"y\")];return [row0,row1];}",
            IrJsOptions {
                mangle_identifiers: false,
                operand_order_fusion: true,
                aggregate_operand_order_fusion: true,
                ..IrJsOptions::default()
            },
        );
        let cb_x = foreign_gap.find("cb(\"x\")").expect(&foreign_gap);
        let gap = foreign_gap.find("gap()").expect(&foreign_gap);
        assert!(cb_x < gap, "{foreign_gap}");
    }

    #[test]
    fn aggregate_operand_fusion_materializes_observable_chained_reads() {
        let code = compile_with_options(
            "extern bool test(JsValue value);extern JsValue rows();extern JsValue candidate();extern void run(func(JsValue)->void callback);void install(JsValue tuples,JsValue selected){JsValue makeResolve=(float depth,JsValue deferred,JsValue handler,JsValue special=null)=>{return handler;};run((JsValue value)=>{JsValue progress=null;if(test(selected)){progress=selected;}JS.invoke(tuples[0][3],\"add\",JS.call(makeResolve,JS.undefined(),0.0,value,progress,value[\"notifyWith\"]));JsValue fulfilled=null;if(test(selected)){fulfilled=selected;}JS.invoke(tuples[1][3],\"add\",JS.call(makeResolve,JS.undefined(),0.0,value,fulfilled));JsValue rejected=null;if(test(selected)){rejected=selected;}JS.invoke(tuples[2][3],\"add\",JS.call(makeResolve,JS.undefined(),0.0,value,rejected));});}install(rows(),candidate());",
            IrJsOptions {
                mangle_identifiers: false,
                operand_order_fusion: true,
                aggregate_operand_order_fusion: true,
                ..IrJsOptions::default()
            },
        );

        let trace = run_javascript(&format!(
            "let hits=[];function test(){{return true}}function rows(){{return [[0,0,0,{{add(value){{hits.push(value)}}}}],[0,0,0,{{add(value){{hits.push(value)}}}}],[0,0,0,{{add(value){{hits.push(value)}}}}]]}}function candidate(){{return 7}}function run(callback){{callback({{notifyWith:null}})}};{code};process.stdout.write(hits.join(','))"
        ));
        assert_eq!(trace, "7,7,7", "{code}");
    }

