    #[test]
    fn keeps_captured_callee_off_a_later_process_slot() {
        let code = compile_module(
            "extern JsValue hook();export JsValue run(JsValue special){JsValue mightThrow=()=>{return 1.0;};JsValue process=mightThrow;if(!special.truthy()){process=()=>{mightThrow();return JS.undefined();};}process[\"error\"]=hook();return process;}",
        );
        assert!(
            !code.contains(".error=")
                || !code
                    .split(".error=")
                    .next()
                    .unwrap_or("")
                    .rsplit([',', ';', '{', '('])
                    .next()
                    .unwrap_or("")
                    .contains('='),
            "{code}"
        );
        let after_try = code.split("try{").nth(1).unwrap_or("");
        let called = after_try.split('(').next().unwrap_or("");
        let error_object = code
            .split(".error=")
            .next()
            .and_then(|prefix| prefix.rsplit(['=', ',', ';', '{', '(']).next())
            .unwrap_or("");
        assert_ne!(called.trim(), error_object.trim(), "{code}");
    }

    #[test]
    fn coalesces_sequential_mutations_across_direct_phi_edges() {
        let source = "export int refine(int hash,int remaining,int byte){if(remaining==3){hash^=byte<<16;}if(remaining>=2){hash^=byte<<8;}if(remaining>=1){hash^=byte;hash=Math.imul(hash,31);}return hash;}";
        let code = compile_module(source);
        let direct = compile_module_with_options(
            source,
            IrJsOptions {
                phi_affinity_mode: PhiAffinityMode::Direct,
                ..IrJsOptions::default()
            },
        );
        let conservative = compile_module_with_options(
            source,
            IrJsOptions {
                phi_affinity_mode: PhiAffinityMode::Conservative,
                ..IrJsOptions::default()
            },
        );

        assert!(!code.contains("else{"), "{code}");
        assert_eq!(direct, conservative);
        assert!(code.len() <= direct.len(), "{code}\n{direct}");
        assert!(direct.contains("Math.imul(a^c,31)"), "{direct}");
    }

