    #[test]
    fn loop_index_copied_from_a_call_keeps_progress_when_a_sibling_captures_it() {
        let source = r#"
            int startAt(string group){
              if(group.length==0){return -1;}
              return 0;
            }
            int scan(string group){
              int splitAt=startAt(group);
              if(splitAt<0){return 0;}
              int compoundEnd=group.length;
              int i=splitAt;
              int depth=0;
              string quote="";
              for(;i<group.length;i=i+1){
                string c=group.charAt(i);
                if(quote!=""){
                  if(c==quote){quote="";}
                  continue;
                }
                if(c=="\""||c=="'"){quote=c;continue;}
                if(c=="("){depth=depth+1;continue;}
                if(c==")"){depth=depth-1;continue;}
                if(depth==0&&(c==" "||c==">")){
                  compoundEnd=i;
                  break;
                }
              }
              return compoundEnd;
            }
            print(scan(":header"));
            print(scan("ab cd"));
        "#;
        let default_output =
            compile_without_inlining_with_options(source, false, IrJsOptions::default());
        assert_eq!(
            run_javascript(&default_output),
            "7\n2\n",
            "{default_output}"
        );
        let compact_output = compile_with_options(
            source,
            IrJsOptions {
                mangle_identifiers: true,
                phi_affinity_mode: PhiAffinityMode::Grouped,
                comma_expressions: true,
                update_loop_layout: true,
                conditional_expressions: true,
                cross_scope_name_reuse: true,
                local_name_reserve: 8,
                ..IrJsOptions::default()
            },
        );
        assert_eq!(
            run_javascript(&compact_output),
            "7\n2\n",
            "{compact_output}"
        );
    }

    #[test]
    fn local_phi_expression_keeps_incoming_slots_live_until_the_result_use() {
        let source = "struct Point{int x;int y;}struct Rect{Point origin;int width;int height;}int area(Rect rect){return rect.width*rect.height+rect.origin.x+rect.origin.y;}int[] values=[3,1,4,1,5,9];int total=0;for(int i=0;i+3<values.length;i+=4){int w=values[i+2];int h=values[i+3];if(w==0){w=1;}if(h==0){h=1;}total+=area(Rect{Point{values[i],values[i+1]},w,h});}print(total);";
        let arena = Bump::new();
        let program = parse_source(&arena, source).unwrap();
        let semantics = analyze(&program).unwrap();
        let mut ir = lower_to_control_flow(&program, &semantics).unwrap();
        optimize_control_flow(&mut ir).unwrap();
        let integer_analysis = analyze_integer_values(&ir);
        let function = ir
            .functions
            .iter()
            .find(|function| function.kind == FunctionKind::Entry)
            .unwrap();
        let height_local = function
            .locals
            .iter()
            .find(|local| local.name == "h")
            .map(|local| local.id)
            .unwrap();
        let height_phi = function
            .blocks
            .iter()
            .flat_map(|block| &block.phis)
            .find(|phi| phi.origin.local() == Some(height_local))
            .unwrap();
        let point = function
            .blocks
            .iter()
            .flat_map(|block| &block.instructions)
            .find_map(|instruction| match (&instruction.op, instruction.out) {
                (ControlFlowOp::Struct { name: "Point", .. }, Some(out)) => Some(out),
                _ => None,
            })
            .unwrap();

        for mode in [PhiAffinityMode::Direct, PhiAffinityMode::Conservative] {
            let options = IrJsOptions {
                phi_affinity_mode: mode,
                local_phi_expression_regions: true,
                ..IrJsOptions::default()
            };
            let context = LocalNames::new(
                function,
                integer_analysis.function(function.id),
                false,
                &Mangler::default(),
                &AHashMap::default(),
                &AHashMap::default(),
                &AHashMap::default(),
                &options,
                &AHashSet::default(),
                &loop_captured_closures(function),
                &AHashMap::default(),
            );
            let height_incoming = height_phi
                .incoming
                .iter()
                .map(|(_, value)| *value)
                .find(|value| context.is_stored(*value))
                .expect("the non-constant height arm must have a JavaScript slot");
            assert_ne!(
                context.value_name(height_incoming).unwrap(),
                context.value_name(point).unwrap(),
                "{mode:?} coloring must not overwrite an incoming value referenced by the recovered conditional"
            );
        }
    }

    #[test]
    fn local_phi_expression_does_not_read_a_coalesced_input_before_its_definition() {
        let source = r#"
            struct Result { string raw; string text; }
            string trimValue(string value) {
                while (value.endsWith(" ")) value = value.slice(0, value.length - 1);
                return value;
            }
            Result? tokenize(bool preserve, string source) {
                JsValue matchValue = new Regex("^a", "u").exec(source);
                if (JS.isNullish(matchValue)) return null;
                string value = JS.string(matchValue[0]);
                if (!preserve) value = trimValue(value);
                Result result = Result{value, ""};
                result.text = value.replace(new Regex(".", "u"), "x");
                return result;
            }
            extern bool readBool();
            extern string readString();
            Result? result = tokenize(readBool(), readString());
            if (result != null) print(result.raw + result.text);
        "#;
        let output = compile_with_options(source, IrJsOptions::default());
        let instrumented = format!(
            "globalThis.readBool=()=>false;globalThis.readString=()=>\"a\";let calls=0;let endsWith=String.prototype.endsWith;String.prototype.endsWith=function(...args){{calls++;return endsWith.call(this,...args)}};{output};console.log(calls)"
        );

        assert_eq!(run_javascript(&instrumented), "ax\n1\n", "{output}");
    }

    #[test]
    fn emits_cross_chunk_imports_and_live_global_exports() {
        let arena = Bump::new();
        let program = parse_source(
            &arena,
            "int base=40;void setBase(int value){base=value;}int read(){return base;}int apply(int value){return read()+value;}export{setBase,read,apply};",
        )
        .unwrap();
        let semantics = analyze(&program).unwrap();
        let mut ir = lower_to_control_flow(&program, &semantics).unwrap();
        optimize_control_flow_for_module(&mut ir).unwrap();
        let read = ir
            .functions
            .iter()
            .find(|function| function.name == Some("read"))
            .unwrap()
            .id;
        let chunks = emit_optimized_ir_js_chunks_with_options(
            &ir,
            &IrJsOptions {
                string_quote: StringQuote::Template,
                ..IrJsOptions::default()
            },
            &IrJsChunkPlan {
                entry_file: "entry\".js".to_string(),
                chunks: vec![IrJsChunkSpec {
                    file_name: "shared.js".to_string(),
                    functions: vec![read],
                    lazy_module: None,
                }],
            },
        )
        .unwrap();

        assert_eq!(chunks.len(), 2);
        assert_eq!(chunks[0].file_name, "entry\".js");
        assert_eq!(chunks[1].file_name, "shared.js");
        assert!(chunks[0].code.contains("from\"./shared.js\""));
        assert!(chunks[1].code.contains("from'./entry\".js'"));
        assert!(chunks[0].code.contains(" as apply"));
        assert!(chunks[0].code.contains(" as read"));
        for chunk in &chunks {
            assert!(!chunk.code.contains("from`"), "{}", chunk.code);
            assert_javascript_module_parses(&chunk.code);
        }

        let error = emit_optimized_ir_js_chunks_with_options(
            &ir,
            &IrJsOptions::default(),
            &IrJsChunkPlan {
                entry_file: "entry.js".to_string(),
                chunks: vec![IrJsChunkSpec {
                    file_name: "entry.js".to_string(),
                    functions: vec![read],
                    lazy_module: None,
                }],
            },
        )
        .unwrap_err();
        assert!(error.message.contains("duplicate chunk file name"));
    }

