    #[test]
    fn rewrites_block_arrows_as_boundary_object_methods() {
        let arrow = JsExpression::raw("(a,b)=>{return a+b}", JsPrecedence::Assignment);
        assert_eq!(
            arrow_block_as_object_method("apply", &arrow).as_deref(),
            Some("apply(a,b){return a+b}")
        );
        let expression = JsExpression::raw("a=>a+1", JsPrecedence::Assignment);
        assert!(arrow_block_as_object_method("apply", &expression).is_none());
        let wrapped = JsExpression::raw("bindMethodRest((a,b)=>{return a+b})", JsPrecedence::Call);
        assert!(arrow_block_as_object_method("apply", &wrapped).is_none());
        let method = JsExpression::raw("function(){return this}", JsPrecedence::Primary);
        assert!(object_method_shorthand("empty", &method).is_none());
    }

    #[test]
    fn groups_empty_parameter_arrows_used_as_call_targets() {
        let arrow = JsExpression::raw("()=>($++,$)", JsPrecedence::Assignment);
        assert_eq!(JsExpression::call(arrow, []).code, "(()=>($++,$))()");

        let already_grouped = JsExpression::grouped(
            "()=>($++,$)".to_string(),
            JsPrecedence::Assignment,
            JsExpressionRoot::Raw,
        );
        assert_eq!(
            JsExpression::call(already_grouped, []).code,
            "(()=>($++,$))()"
        );
    }

