    #[test]
    fn orders_acyclic_phi_copies_and_preserves_cycles() {
        let assignments = vec![
            ("b".to_string(), "(b+Math.imul(a,2)|0)".to_string()),
            ("a".to_string(), "(a+1|0)".to_string()),
        ];
        assert_eq!(
            order_scalar_assignments(&assignments).unwrap(),
            vec![("b", "(b+Math.imul(a,2)|0)"), ("a", "(a+1|0)")]
        );

        let swap = vec![
            ("a".to_string(), "b".to_string()),
            ("b".to_string(), "a".to_string()),
        ];
        assert!(order_scalar_assignments(&swap).is_none());
        assert_eq!(
            scalar_parallel_assignments(&swap, Some(("c", true))),
            Some("var c=a;a=b;b=c;".to_string())
        );
        assert_eq!(
            replace_identifier("a+(data.a||\"a\")", "a", "b"),
            "b+(data.a||\"a\")"
        );
        assert!(!expression_references_name("data.a+'a'", "a"));
        assert_eq!(
            scalar_parallel_assignments(
                &[
                    ("a".to_string(), "b".to_string()),
                    ("b".to_string(), "data.a".to_string()),
                ],
                Some(("c", true)),
            ),
            Some("a=b;b=data.a;".to_string())
        );
        assert_eq!(
            scalar_parallel_assignments(
                &[
                    ("a".to_string(), "b".to_string()),
                    ("b".to_string(), "`${a}`".to_string()),
                ],
                Some(("c", true)),
            ),
            Some("var c=a;a=b;b=`${c}`;".to_string())
        );
    }

    #[test]
    fn declares_orderable_phi_copies_as_var_bindings_not_arrays() {
        let output = compile(
            r#"
                extern JsValue arguments;
                export JsValue extend() {
                    JsValue target = JS.or(arguments[0], JS.object());
                    float i = 1.0;
                    bool deep = false;
                    if (target is bool) {
                        deep = target;
                        target = JS.or(arguments[1], JS.object());
                        i = 2.0;
                    }
                    if (deep) {
                        return target;
                    }
                    return i;
                }
            "#,
        );
        assert!(
            !output.contains("]=["),
            "parallel copies should stay scalar bindings: {output}"
        );
    }

    #[test]
    fn merges_matching_branch_assignments() {
        assert_eq!(
            merge_conditional_assignments("a=(a+1|0);", "a=(a-1|0);"),
            Some((false, "a", "(a+1|0)", "(a-1|0)", ""))
        );
        assert_eq!(
            merge_conditional_assignments("var a=1;", "a=0;"),
            Some((true, "a", "1", "0", ""))
        );
        assert_eq!(
            merge_conditional_assignments("var a=1,b,c;", "a=0;"),
            Some((true, "a", "1", "0", ",b,c"))
        );
        assert!(merge_conditional_assignments("a=1;", "b=2;").is_none());
    }

    #[test]
    fn renders_distinct_branch_assignments_as_an_expression() {
        assert_eq!(
            conditional_assignment_expression("a=b;", "c=d;"),
            Some(("a", "b", "c", "d"))
        );
        assert!(conditional_assignment_expression("var a=b;", "c=d;").is_none());

        let output = compile(
            "extern int read();int left=0;int right=0;void route(int value){if(value>0){left=value;}else{right=value;}}route(read());print(left+right);",
        );
        assert!(output.contains("?"), "{output}");
        assert!(!output.contains("else"), "{output}");
    }

    #[test]
    fn renders_shortest_exact_numeric_literals() {
        assert_eq!(shortest_integer(120_000), "12e4");
        assert_eq!(shortest_integer(1_099_511_627_776), "(2**40)");
        // `(2**16)` is longer than `65536`, so the decimal wins once the
        // spelling pays for the parentheses that make it a primary expression.
        assert_eq!(shortest_integer(65_536), "65536");
        assert_eq!(shortest_integer(256), "256");
        assert_eq!(shortest_float(1_099_511_627_776.0), "(2**40)");
        assert_eq!(shortest_float(0.5), ".5");
        assert_eq!(shortest_float(0.0000001), "1e-7");
        assert_eq!(shortest_float(-0.25), "-.25");
    }

    #[test]
    fn derives_identifier_alphabets_from_emitted_character_frequency() {
        let alphabet = IdentifierAlphabet::for_code("nnnnnnneeeeett");
        assert_eq!(encode_identifier(0, &alphabet), "n");
        assert_eq!(encode_identifier(1, &alphabet), "e");
        assert_eq!(encode_identifier(2, &alphabet), "t");
        assert_eq!(
            IdentifierAlphabet::for_code(""),
            IdentifierAlphabet::canonical()
        );
        assert_ne!(
            IdentifierAlphabet::javascript_keyword(),
            IdentifierAlphabet::canonical()
        );
        assert_eq!(
            encode_identifier(0, &IdentifierAlphabet::javascript_keyword()),
            "e"
        );

        let mut binding_characters = [0usize; 128];
        binding_characters[b'n' as usize] = 7;
        let contextual = IdentifierAlphabet::for_code_excluding_binding_characters(
            "nnnnnnneeeeett",
            &binding_characters,
        );
        assert_eq!(encode_identifier(0, &contextual), "e");
        assert_eq!(encode_identifier(1, &contextual), "t");
    }

    #[test]
    fn frequency_ordered_local_names_prioritize_hot_interference_colors() {
        let source = "extern void sink(int value);export void run(int cold,int hot){sink(hot);sink(hot);sink(hot);sink(cold);}";
        let baseline = compile_module_with_options(
            source,
            IrJsOptions {
                mangle_identifiers: true,
                mangle_exports: false,
                function_spelling: FunctionSpelling::Function,
                frequency_order_local_names: false,
                ..IrJsOptions::default()
            },
        );
        let weighted = compile_module_with_options(
            source,
            IrJsOptions {
                mangle_identifiers: true,
                mangle_exports: false,
                function_spelling: FunctionSpelling::Function,
                frequency_order_local_names: true,
                ..IrJsOptions::default()
            },
        );

        assert!(baseline.contains("function a(a,b)"), "{baseline}");
        assert!(
            baseline.contains("sink(b);sink(b);sink(b);sink(a)"),
            "{baseline}"
        );
        assert!(weighted.contains("function a(b,a)"), "{weighted}");
        assert!(
            weighted.contains("sink(a);sink(a);sink(a);sink(b)"),
            "{weighted}"
        );
    }

    #[test]
    fn renders_semantically_equivalent_single_quoted_strings() {
        assert_eq!(
            render_string_literal(r#"say \"hi\" and it's\nready"#, StringQuote::Single),
            r#"'say "hi" and it\'s\nready'"#
        );
    }

    #[test]
    fn quote_variants_preserve_non_json_javascript_string_payloads() {
        // The raw tab is valid in a JavaScript string but invalid in a JSON
        // string. The preceding `\\n` must remain one regex escape at runtime,
        // rather than becoming a regex that matches a literal backslash.
        let pattern = "^a\\\\nb\t$";
        let double = render_string_literal(pattern, StringQuote::Double);
        for quote in [StringQuote::Single, StringQuote::Template] {
            let rendered = render_string_literal(pattern, quote);
            assert_eq!(rendered, double);
            assert_eq!(
                run_javascript(&format!(
                    "process.stdout.write(String(new RegExp({rendered}).test('a\\nb\\t')))"
                )),
                "true",
                "{rendered}"
            );
        }
    }

