    #[test]
    fn declares_locals_when_unused_params_are_elided() {
        let output = compile_module(
            r#"
export extern void use(int v);
export extern void schedule(func(int)->void cb);
int[] items = [];
void readAll(int unusedParam) {
  int resolveIndex = 0;
  int resolveCount = items.length;
  while (resolveIndex < resolveCount) {
    use(items[resolveIndex]);
    resolveIndex = resolveIndex + 1;
  }
}
schedule(readAll);
"#,
        );
        assert!(
            output.contains("var "),
            "elided unused params must not suppress local var declarations: {output}"
        );
        let bare_counter = output.contains("for(a=0")
            || output.contains("for(b=0")
            || output.contains("for(c=0")
            || output.contains("for(d=0")
            || output.contains("for(e=0")
            || output.contains("for(f=0")
            || output.contains("for(g=0")
            || output.contains("for(h=0")
            || output.contains("for(i=0")
            || output.contains("for(j=0");
        assert!(
            !bare_counter,
            "loop counter must be declared before for-update use: {output}"
        );
    }

    #[test]
    fn keeps_loop_counter_init_after_inlined_null_check() {
        let output = compile_module(
            r#"
export extern class Console { void log(string s); }
export extern Console console;
int? CUR = null;
int useState(int initial) {
  if (CUR == null) {
    CUR = initial;
    return initial;
  }
  int cur = CUR;
  return cur;
}
export void run() {
  int n = useState(0);
  string[] list = [];
  list.push("a");
  list.push("b");
  string[] out = [];
  int li = 0;
  while (li < list.length) {
    out.push(list[li]);
    li = li + 1;
  }
  console.log(n.toString() + ":" + out.length.toString());
}
"#,
        );
        let collapsed = output.replace('\n', "");
        let while_idx = collapsed
            .find("while(")
            .unwrap_or_else(|| panic!("expected a while loop: {output}"));
        let counter = collapsed[while_idx + "while(".len()..]
            .split('<')
            .next()
            .expect("while condition");
        assert!(
            !counter.is_empty() && counter.bytes().all(is_js_identifier_byte),
            "could not parse loop counter from: {output}"
        );
        let prefix = &collapsed[..while_idx];
        let assigned = prefix.contains(&format!("{counter}=0"))
            || prefix.contains(&format!("var {counter}=0"))
            || prefix
                .split("var ")
                .any(|chunk| chunk.starts_with(&format!("{counter}=0")));
        assert!(
            assigned,
            "loop counter `{counter}` must be assigned 0 before the loop: {output}"
        );
    }

